steps.code:
# Let's verify the final Venmo friend list matches the phone friends
venmo_friends_final = []
page_index = 0
page_limit = 20

while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    friends = resp if isinstance(resp, list) else resp.get("friends", [])
    venmo_friends_final.extend(friends)
    if len(friends) < page_limit:
        break
    page_index += 1

print(f"Final venmo friends: {len(venmo_friends_final)}")
for f in venmo_friends_final:
    print(f"{f['first_name']} {f['last_name']} - {f['email']}")

# Check if they match phone friends
venmo_final_emails = {f['email'] for f in venmo_friends_final}
phone_friend_emails = {c['email'] for c in phone_friends}

if venmo_final_emails == phone_friend_emails:
    print("SUCCESS: Venmo friends match phone friends!")
else:
    print("MISMATCH: Venmo friends do not match phone friends")
    print(f"Missing from venmo: {phone_friend_emails - venmo_final_emails}")
    print(f"Extra in venmo: {venmo_final_emails - phone_friend_emails}")

