phone_contacts = apis.phone.search_contacts(access_token=phone_token, relationship="friend", page_limit=100)

# Extract emails from venmo friends
venmo_emails = set()
for friend in venmo_friends:
    if 'email' in friend:
        venmo_emails.add(friend['email'])
    elif 'user_email' in friend:
        venmo_emails.add(friend['user_email'])

# Extract emails from phone friends
phone_emails = set()
for contact in phone_contacts:
    if 'email' in contact:
        phone_emails.add(contact['email'])
    elif 'emails' in contact:
        phone_emails.update(contact['emails'])

# Compute to remove: venmo friends not in phone friends
to_remove = venmo_emails - phone_emails
print("To remove:", to_remove)

# Fetch venmo friends with valid page_limit and handle pagination
venmo_friends = []
page_index = 0
while True:
    page = apis.venmo.search_friends(access_token=venmo_token, page_limit=20, page_index=page_index)
    if not page:
        break
    venmo_friends.extend(page)
    if len(page) < 20:
        break
    page_index += 1

