steps.code:
# Parse the old songs list from the file content
old_songs = []
for line in file_content['content'].splitlines():
    line = line.strip()
    if line.startswith('- '):
        song_str = line[2:]
        # Format: "Title by Artist" or "Title by Artist1, Artist2"
        if ' by ' in song_str:
            title_part, artist_part = song_str.split(' by ', 1)
            old_songs.append({'title': title_part.strip(), 'artists': [a.strip() for a in artist_part.split(',')]})
        else:
            # Just title, no artist
            old_songs.append({'title': song_str.strip(), 'artists': []})

print(f"Parsed {len(old_songs)} old songs")
for s in old_songs:
    print(s)

