# Let's search for each old song and find its song_id
# We'll store the mapping from song title to song_id
song_id_map = {}
for song in songs_to_archive:
    title = song['title']
    artists = song['artists']
    # Search for the song
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'])
    # Find the matching result
    found = None
    for result in results:
        if result['title'].lower() == title.lower():
            # Check if all artists are present
            result_artist_names = [artist['name'].lower() for artist in result['artists']]
            if all(artist.lower() in result_artist_names for artist in artists):
                found = result
                break
    if found:
        song_id_map[title] = found['song_id']
        print(f"Found: {title} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {', '.join(artists)}")
print("song_id_map:", song_id_map)

