target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [513, 514, 515, 516, 517, 518, 519]

# Check each playlist for any remaining target songs
for pid in playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = {song['id'] for song in playlist['songs']}
    remaining = song_ids & target_song_ids
    if remaining:
        print(f"Playlist {pid} still contains target songs: {remaining}")
    else:
        print(f"Playlist {pid} clean")

# Check new playlist contains all target songs
new_playlist = apis.spotify.show_playlist(playlist_id=654, access_token=spotify_token)
new_song_ids = {song['id'] for song in new_playlist['songs']}
missing = target_song_ids - new_song_ids
if missing:
    print(f"New playlist missing target songs: {missing}")
else:
    print("New playlist contains all target songs")

