steps.code:
# Search for each song in the list to find their Spotify song IDs
song_ids_to_archive = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artists'][0]}"
    result = apis.spotify.search_songs(query=query, access_token=spotify_token)
    print(f"Search for '{query}':")
    print(result)
    # We'll collect the first result that matches title and artist
    if result:
        # Find the best match
        for item in result:
            if item['title'].lower() == song['title'].lower():
                # Check if any artist matches
                artist_names = [a['name'] for a in item['artists']]
                if any(artist.lower() in [a.lower() for a in song['artists']] for artist in artist_names):
                    song_ids_to_archive.append(item['song_id'])
                    break
        else:
            # If no exact match, just take first result
            song_ids_to_archive.append(result[0]['song_id'])
    else:
        print(f"No results for {query}")

print("Song IDs to archive:", song_ids_to_archive)

