steps.code:
# Update the note content with release dates
new_lines = []
for line in lines:
    if 'RELEASED_AT TODO' in line:
        # Extract title from line
        match = re.match(r'^- (.+?) BY (.+?) RELEASED_AT TODO$', line.strip())
        if match:
            title = match.group(1).strip()
            if title in release_dates:
                new_line = line.replace('RELEASED_AT TODO', f'RELEASED_AT {release_dates[title]}')
                new_lines.append(new_line)
                print(f"Updated: {new_line}")
            else:
                print(f"No release date for {title}")
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print("New content:")
print(new_content)

