steps.code:
# Search for release dates for all songs with TODO
release_dates = {}

# We'll search for each song using title+artist (no spaces) as query
for song in todo_songs:
    query = song['title'].replace(' ', '') + song['artist'].replace(' ', '')
    results = apis.spotify.search_songs(query=query)
    # Find the matching song in results
    found = None
    for r in results:
        if r['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for a in r['artists']:
                if a['name'].lower() == song['artist'].lower():
                    found = r
                    break
            if found:
                break
    if found:
        release_date = found['release_date']  # ISO format
        # Extract month and year
        month = release_date[5:7]
        year = release_date[0:4]
        release_dates[song['title']] = f"{month}/{year}"
        print(f"{song['title']} -> {month}/{year}")
    else:
        print(f"NOT FOUND: {song['title']}")

